package org.example.payment.dto;

import jakarta.validation.constraints.*;

import java.math.BigDecimal;

public record CreatePaymentRequest(
        @NotBlank(message = "idempotencyKey is required")
        @Size(max = 64, message = "idempotencyKey max length is 64")
        String idempotencyKey,

        @NotBlank(message = "sourceAccount is required")
        @Pattern(regexp = "^[0-9]{8,20}$", message = "sourceAccount must be 8-20 digits")
        String sourceAccount,

        @NotBlank(message = "destinationAccount is required")
        @Pattern(regexp = "^[0-9]{8,20}$", message = "destinationAccount must be 8-20 digits")
        String destinationAccount,

        @DecimalMin(value = "0.01", message = "amount must be greater than 0")
        @DecimalMax(value = "1000000.00", message = "amount must not exceed 1,000,000")
        @Digits(integer = 12, fraction = 2, message = "amount must have up to 2 decimal places")
        BigDecimal amount,

        @NotBlank(message = "currency is required")
        @Pattern(regexp = "^[A-Z]{3}$", message = "currency must be ISO-4217 format (e.g. USD)")
        String currency,

        @Size(max = 140, message = "reference max length is 140")
        String reference
) {
}

package org.example.payment.dto;

import jakarta.validation.constraints.*;

import java.math.BigDecimal;

/**
 * Request payload for creating a new payment.
 *
 * @param idempotencyKey unique key to prevent duplicate payment creation
 * @param sourceAccount source account number
 * @param destinationAccount destination account number
 * @param amount transfer amount
 * @param currency payment currency in ISO-4217 format
 * @param reference optional payment reference
 */
public record CreatePaymentRequest(
        @NotBlank(message = "idempotencyKey is required")
        @Size(max = 64, message = "idempotencyKey max length is 64")
        String idempotencyKey,

        @NotBlank(message = "sourceAccount is required")
        @Pattern(regexp = "^[0-9]{8,20}$", message = "sourceAccount must be 8-20 digits")
        String sourceAccount,

        @NotBlank(message = "destinationAccount is required")
        @Pattern(regexp = "^[0-9]{8,20}$", message = "destinationAccount must be 8-20 digits")
        String destinationAccount,

        @DecimalMin(value = "0.01", message = "amount must be greater than 0")
        @DecimalMax(value = "1000000.00", message = "amount must not exceed 1,000,000")
        @Digits(integer = 12, fraction = 2, message = "amount must have up to 2 decimal places")
        BigDecimal amount,

        @NotBlank(message = "currency is required")
        @Pattern(regexp = "^[A-Z]{3}$", message = "currency must be ISO-4217 format (e.g. USD)")
        String currency,

        @Size(max = 140, message = "reference max length is 140")
        String reference
) {
}

package org.example.payment.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

public record FailPaymentRequest(
        @NotBlank(message = "errorCode is required")
        @Size(max = 64, message = "errorCode max length is 64")
        String errorCode,

        @NotBlank(message = "errorMessage is required")
        @Size(max = 255, message = "errorMessage max length is 255")
        String errorMessage
) {
}

package org.example.payment.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Request payload for marking a payment as failed.
 *
 * @param errorCode business or system error code
 * @param errorMessage human-readable error message
 */
public record FailPaymentRequest(
        @NotBlank(message = "errorCode is required")
        @Size(max = 64, message = "errorCode max length is 64")
        String errorCode,

        @NotBlank(message = "errorMessage is required")
        @Size(max = 255, message = "errorMessage max length is 255")
        String errorMessage
) {
}

package org.example.payment.dto;

import org.example.payment.model.PaymentStatus;

import java.time.LocalDateTime;

public record PaymentHistoryResponse(
        Long id,
        String paymentId,
        PaymentStatus fromStatus,
        PaymentStatus toStatus,
        String errorCode,
        String errorMessage,
        String triggeredBy,
        LocalDateTime changedAt
) {
}

package org.example.payment.dto;

import org.example.payment.model.PaymentStatus;

import java.time.LocalDateTime;

/**
 * Response item for one payment status change in history.
 *
 * @param id history row id
 * @param paymentId payment identifier
 * @param fromStatus previous payment status
 * @param toStatus new payment status
 * @param errorCode error code recorded for this change
 * @param errorMessage error message recorded for this change
 * @param triggeredBy actor or system that triggered this change
 * @param changedAt time when the status changed
 */
public record PaymentHistoryResponse(
        Long id,
        String paymentId,
        PaymentStatus fromStatus,
        PaymentStatus toStatus,
        String errorCode,
        String errorMessage,
        String triggeredBy,
        LocalDateTime changedAt
) {
}

package org.example.payment.dto;

import org.example.payment.model.PaymentStatus;

import java.math.BigDecimal;
import java.time.LocalDateTime;

public record PaymentResponse(
        String id,
        String idempotencyKey,
        String sourceAccount,
        String destinationAccount,
        BigDecimal amount,
        String currency,
        String reference,
        PaymentStatus status,
        String errorCode,
        String errorMessage,
        LocalDateTime createdAt,
        LocalDateTime updatedAt
) {
}

package org.example.payment.dto;
import org.example.payment.model.PaymentStatus;
import java.math.BigDecimal; import java.time.LocalDateTime;
/** * Response payload with payment details. * * @param id payment identifier * @param idempotencyKey client idempotency key * @param sourceAccount source account number * @param destinationAccount destination account number * @param amount transfer amount * @param currency payment currency * @param reference optional payment reference * @param status current payment status * @param errorCode error code when payment fails * @param errorMessage error message when payment fails * @param createdAt creation timestamp * @param updatedAt last update timestamp */ public record PaymentResponse( String id, String idempotencyKey, String sourceAccount, String destinationAccount, BigDecimal amount, String currency, String reference, PaymentStatus status, String errorCode, String errorMessage, LocalDateTime createdAt, LocalDateTime updatedAt ) { }
